"""
Abstraction function and business invariants for rq (v2.x), computed from a
Redis snapshot.

Snapshot format: {key: {"t": type, "v": value, "ttl": bool}}.

What the user-level state contains:
  queues  - for each queue: whether Queue.all() lists it, the jobs waiting in
            order, the jobs a worker is picking up right now, and the jobs in
            each registry (started, finished, failed, deferred, scheduled,
            canceled).
  jobs    - for each job hash that exists: status, queue, description, worker,
            dependencies, dependents, retries left, timeout, whether the job
            will expire, and its live executions.
  workers - for each worker: state, current job and job counters.
  results - each job's recorded results, oldest first. These are kept apart
            from "jobs" because results can outlive a deleted job.

Left out as implementation detail: timestamps (already masked), serialized
payloads, heartbeats, first-seen markers, execution-registry scores.

About the third example snapshot: the job was canceled while it was running,
and the worker then marked it finished. The job ends up "finished" but still
sits in the canceled registry. The invariant
canceled_registry_holds_only_canceled_jobs is False on that snapshot on
purpose: it reports that race. There is a known false positive: re-enqueueing
a canceled job under the same id leaves a stale entry in the canceled registry.

Known short gaps inside multi-step rq operations, where a "status -> registry"
invariant can briefly be False:
  - FailedJobRegistry.requeue removes the registry entry before it enqueues.
  - A retry with an interval sets the "scheduled" status outside the pipeline.
  - A worker that listens on several queues pops with LPOP and does not use
    the intermediate list.
"""
import json

_JOB_PREFIX = "rq:job:"
_QUEUE_PREFIX = "rq:queue:"
_INTERMEDIATE_SUFFIX = ":intermediate"
_REGISTRY_PREFIXES = {
    "started": "rq:wip:",
    "finished": "rq:finished:",
    "failed": "rq:failed:",
    "deferred": "rq:deferred:",
    "scheduled": "rq:scheduled:",
    "canceled": "rq:canceled:",
}
_REGISTRY_KINDS = ["started", "finished", "failed", "deferred", "scheduled", "canceled"]
_STATUSES = {
    "created", "queued", "finished", "failed", "started",
    "deferred", "scheduled", "stopped", "canceled",
}
_RESULT_TYPES = {"1": "successful", "2": "failed", "3": "stopped", "4": "retried"}


def _members(value):
    """Turn a set (list of str) or a zset (list of [member, score]) into a list of str."""
    out = []
    if isinstance(value, list):
        for item in value:
            if isinstance(item, (list, tuple)):
                if item:
                    out.append(str(item[0]))
            elif item is not None:
                out.append(str(item))
    return out


def _to_int(value):
    try:
        return int(str(value))
    except Exception:
        return None


def _text(value):
    """Return a non-empty string, or None for missing or empty values."""
    if value is None:
        return None
    s = str(value)
    return s if s != "" else None


def _dependency_ids(job_hash, dependency_set):
    raw = job_hash.get("dependency_ids")
    if raw:
        try:
            parsed = json.loads(str(raw))
            if isinstance(parsed, list):
                return sorted({str(x) for x in parsed})
        except Exception:
            pass
    single = _text(job_hash.get("dependency_id"))
    if single:
        return [single]
    return sorted(set(dependency_set or []))


def _model(snap):
    """Parse the snapshot into raw building blocks. Never raises."""
    if not isinstance(snap, dict):
        snap = {}

    jobs = {}               # job id -> (hash, has_ttl)
    dependents = {}         # job id -> [ids of jobs that depend on it]
    dependency_sets = {}    # job id -> [ids it depends on] (fallback source)
    waiting = {}            # queue name -> [job ids], in queue order
    picking_up = {}         # queue name -> [job ids] in the intermediate list
    registries = {}         # (kind, queue name) -> sorted [job ids]
    registered = set()      # queue names listed in rq:queues
    workers = {}            # worker name -> hash
    results = {}            # job id -> [stream entries]
    executions = {}         # job id -> [(execution id, worker name)]

    for key in sorted(k for k in snap if isinstance(k, str)):
        entry = snap.get(key)
        if not isinstance(entry, dict):
            continue
        t = entry.get("t")
        v = entry.get("v")

        if key.startswith(_JOB_PREFIX):
            rest = key[len(_JOB_PREFIX):]
            if t == "hash" and isinstance(v, dict) and rest and ":" not in rest:
                jobs[rest] = (v, bool(entry.get("ttl")))
            elif t == "set" and rest.endswith(":dependents"):
                jid = rest[: -len(":dependents")]
                if jid and ":" not in jid:
                    dependents[jid] = sorted(set(_members(v)))
            elif t == "set" and rest.startswith(":") and rest.endswith(":dependencies"):
                # rq writes this key as 'rq:job::<id>:dependencies'
                jid = rest[1: -len(":dependencies")]
                if jid and ":" not in jid:
                    dependency_sets[jid] = sorted(set(_members(v)))

        elif key == "rq:queues" and t == "set":
            for m in _members(v):
                registered.add(m[len(_QUEUE_PREFIX):] if m.startswith(_QUEUE_PREFIX) else m)

        elif key.startswith(_QUEUE_PREFIX) and t == "list" and isinstance(v, list):
            rest = key[len(_QUEUE_PREFIX):]
            if rest.endswith(_INTERMEDIATE_SUFFIX):
                name = rest[: -len(_INTERMEDIATE_SUFFIX)]
                if name:
                    picking_up[name] = [str(x) for x in v]
            elif rest and _INTERMEDIATE_SUFFIX + ":" not in rest:
                waiting[rest] = [str(x) for x in v]

        elif key.startswith("rq:worker:") and t == "hash" and isinstance(v, dict):
            name = key[len("rq:worker:"):]
            if name:
                workers[name] = v

        elif key.startswith("rq:results:") and t == "stream" and isinstance(v, list):
            jid = key[len("rq:results:"):]
            if jid:
                results[jid] = [x for x in v if isinstance(x, dict)]

        elif key.startswith("rq:execution:") and t == "hash" and isinstance(v, dict):
            rest = key[len("rq:execution:"):]
            if ":" in rest:
                jid, exec_id = rest.split(":", 1)
                if jid:
                    executions.setdefault(jid, []).append(
                        (str(v.get("id") or exec_id), _text(v.get("worker_name")))
                    )

        elif t == "zset":
            for kind, prefix in _REGISTRY_PREFIXES.items():
                if key.startswith(prefix):
                    name = key[len(prefix):]
                    if not name:
                        break
                    ids = _members(v)
                    if kind == "started":
                        # started-registry entries are '<job_id>:<execution_id>'
                        ids = [m.split(":", 1)[0] for m in ids]
                    registries[(kind, name)] = sorted(set(ids))
                    break

    queue_names = set(registered) | set(waiting) | set(picking_up)
    queue_names |= {name for (_, name) in registries}
    for job_hash, _ in jobs.values():
        origin = _text(job_hash.get("origin"))
        if origin:
            queue_names.add(origin)

    queues = {}
    for name in sorted(queue_names):
        q = {
            "registered": name in registered,
            "waiting": list(waiting.get(name, [])),
            "being_picked_up": list(picking_up.get(name, [])),
        }
        for kind in _REGISTRY_KINDS:
            q[kind] = list(registries.get((kind, name), []))
        queues[name] = q

    return {
        "jobs": jobs,
        "dependents": dependents,
        "dependency_sets": dependency_sets,
        "queues": queues,
        "workers": workers,
        "results": results,
        "executions": executions,
    }


def _status(job_hash):
    s = _text(job_hash.get("status"))
    return s if s is not None else "created"


def _result_view(entry):
    raw_type = str(entry.get("type", ""))
    view = {
        "type": _RESULT_TYPES.get(raw_type, raw_type or None),
        "worker": _text(entry.get("worker_name")),
        "execution_id": _text(entry.get("execution_id")),
    }
    if _text(entry.get("return_value")) is not None:
        view["return_value"] = str(entry.get("return_value"))
    if _text(entry.get("exc_string")) is not None:
        view["exception"] = str(entry.get("exc_string"))
    return view


def abstract(snap: dict) -> dict:
    """Business-level state, as {variable name: JSON-serialisable value}."""
    try:
        m = _model(snap)
    except Exception:
        return {"queues": {}, "jobs": {}, "workers": {}, "results": {}}

    jobs = {}
    for jid in sorted(m["jobs"]):
        job_hash, has_ttl = m["jobs"][jid]
        timeout = job_hash.get("timeout")
        timeout_int = _to_int(timeout)
        jobs[jid] = {
            "status": _status(job_hash),
            "queue": _text(job_hash.get("origin")),
            "description": _text(job_hash.get("description")),
            "worker": _text(job_hash.get("worker_name")),
            "group": _text(job_hash.get("group_id")),
            "depends_on": _dependency_ids(job_hash, m["dependency_sets"].get(jid)),
            "dependents": list(m["dependents"].get(jid, [])),
            "retries_left": _to_int(job_hash.get("retries_left")),
            "timeout": timeout_int if timeout_int is not None else _text(timeout),
            "will_expire": has_ttl,
            "executions": [
                {"id": eid, "worker": w}
                for eid, w in sorted(m["executions"].get(jid, []), key=lambda x: str(x[0]))
            ],
        }

    workers = {}
    for name in sorted(m["workers"]):
        w = m["workers"][name]
        workers[name] = {
            "state": _text(w.get("state")),
            "current_job": _text(w.get("current_job")),
            "successful_jobs": _to_int(w.get("successful_job_count")) or 0,
            "failed_jobs": _to_int(w.get("failed_job_count")) or 0,
        }

    results = {
        jid: [_result_view(e) for e in entries]
        for jid, entries in sorted(m["results"].items())
        if entries
    }

    return {
        "queues": m["queues"],
        "jobs": jobs,
        "workers": workers,
        "results": results,
    }


def invariants(snap: dict) -> dict:
    """Business invariants, as {invariant name: bool}; True means it holds."""
    names = [
        "job_statuses_are_valid",
        "waiting_jobs_are_queued_on_their_own_queue",
        "queued_jobs_are_waiting_or_being_picked_up",
        "started_jobs_are_in_started_registry",
        "started_jobs_have_a_worker",
        "workers_and_jobs_agree_on_current_job",
        "finished_jobs_are_in_finished_registry",
        "finished_jobs_latest_result_is_successful",
        "failed_jobs_are_in_failed_registry",
        "deferred_jobs_are_in_deferred_registry",
        "deferred_jobs_have_dependencies",
        "deferred_registry_holds_only_deferred_jobs",
        "scheduled_jobs_are_in_scheduled_registry",
        "canceled_jobs_are_in_canceled_registry",
        "canceled_registry_holds_only_canceled_jobs",
        "active_jobs_are_in_one_place",
        "queues_with_waiting_jobs_are_registered",
    ]
    try:
        m = _model(snap)
    except Exception:
        return {n: True for n in names}

    jobs = m["jobs"]
    queues = m["queues"]
    workers = m["workers"]

    def in_queue(kind, qname, jid):
        q = queues.get(qname) if qname else None
        return bool(q) and jid in q.get(kind, [])

    inv = {n: True for n in names}

    for jid, (job_hash, _) in jobs.items():
        status = _status(job_hash)
        origin = _text(job_hash.get("origin"))
        worker = _text(job_hash.get("worker_name"))

        if status not in _STATUSES:
            inv["job_statuses_are_valid"] = False

        if status == "queued":
            if not (in_queue("waiting", origin, jid)
                    or in_queue("being_picked_up", origin, jid)
                    or in_queue("started", origin, jid)):
                inv["queued_jobs_are_waiting_or_being_picked_up"] = False

        if status == "started":
            if not in_queue("started", origin, jid):
                inv["started_jobs_are_in_started_registry"] = False
            if not worker:
                inv["started_jobs_have_a_worker"] = False
            elif worker in workers:
                if _text(workers[worker].get("current_job")) != jid:
                    inv["workers_and_jobs_agree_on_current_job"] = False

        if status == "finished":
            if not in_queue("finished", origin, jid):
                inv["finished_jobs_are_in_finished_registry"] = False
            entries = m["results"].get(jid) or []
            if entries and str(entries[-1].get("type", "")) != "1":
                inv["finished_jobs_latest_result_is_successful"] = False

        if status in ("failed", "stopped") and not in_queue("failed", origin, jid):
            inv["failed_jobs_are_in_failed_registry"] = False

        if status == "deferred":
            if not in_queue("deferred", origin, jid):
                inv["deferred_jobs_are_in_deferred_registry"] = False
            if not _dependency_ids(job_hash, m["dependency_sets"].get(jid)):
                inv["deferred_jobs_have_dependencies"] = False

        if status == "scheduled" and not in_queue("scheduled", origin, jid):
            inv["scheduled_jobs_are_in_scheduled_registry"] = False

        if status == "canceled" and not in_queue("canceled", origin, jid):
            inv["canceled_jobs_are_in_canceled_registry"] = False

        # A job waits, runs, waits for dependencies, or waits for its time.
        # It does only one of these at once. The intermediate (being picked
        # up) list is not counted: it briefly overlaps with the started
        # registry by design.
        places = 0
        for q in queues.values():
            places += q["waiting"].count(jid)
            for kind in ("deferred", "scheduled", "started"):
                if jid in q[kind]:
                    places += 1
        if places > 1:
            inv["active_jobs_are_in_one_place"] = False

    for qname, q in queues.items():
        for jid in q["waiting"]:
            if jid in jobs:  # ids of expired or deleted jobs may linger; rq skips them
                job_hash = jobs[jid][0]
                if _status(job_hash) != "queued" or _text(job_hash.get("origin")) != qname:
                    inv["waiting_jobs_are_queued_on_their_own_queue"] = False
        for jid in q["deferred"]:
            if jid in jobs and _status(jobs[jid][0]) != "deferred":
                inv["deferred_registry_holds_only_deferred_jobs"] = False
        for jid in q["canceled"]:
            if jid in jobs and _status(jobs[jid][0]) != "canceled":
                inv["canceled_registry_holds_only_canceled_jobs"] = False
        if q["waiting"] and not q["registered"]:
            inv["queues_with_waiting_jobs_are_registered"] = False

    for wname, w in workers.items():
        current = _text(w.get("current_job"))
        if current and current in jobs:
            if _text(jobs[current][0].get("worker_name")) != wname:
                inv["workers_and_jobs_agree_on_current_job"] = False

    return inv
